F2 = [['不同来源同一路径', 'items 的 path 相同'], ['创建 Pod', 'conflicting duplicate paths'], ['整体挂载同名键', '被接受'], ['后面的来源覆盖', '']]
F3 = [['来源不存在', 'FailedMount'], ['Pod', 'ContainerCreating'], ['optional: true', '0.9 秒 Running'], ['来源后来出现', '补进目录']]
